Worked example:

```javascript
function findNote(notes,id) {
  return notes.find(note=>note.id === id) ?? null;
}
console.log(findNote([{"id":4,"title":"Moon"},{"id":9,"title":"Sea"}], 9));
```
The returned value is {"id":9,"title":"Sea"}.

after:
```javascript
function findNote(notes,id) {
  return notes.find(note=>note.id === id) ?? null;
}
console.log(findNote([{"id":4,"title":"Moon"},{"id":9,"title":"Sea"}], 9));
```
This returns the note with ID 9 and title Sea. Its ID is 9 even though its array position is 1.
